pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple token that always reverts on transferFrom
        TokenReverter token = new TokenReverter();
        address from = address(0x1234);
        address[] memory tos = new address[](1);
        tos[0] = address(0x5678);
        // Try the call — the reference contract reverts, the buggy one returns true
        bool ok;
        try c.transfer(from, address(token), tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference (correct) reverts so ok == false; buggy contract returns true so ok == true
        assertTrue(!ok);
    }
}

contract TokenReverter {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always revert");
    }
}

