pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a helper contract that implements transferFrom and always returns true
        address helper = address(new Helper());
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);

        bool success;
        // Use try/catch to capture the return value of transfer
        try c.transfer(address(0x5678), helper, tos, 100) returns (bool ret) {
            success = ret;
        } catch {
            success = false;
        }

        // Reference returns true, buggy returns false
        assertTrue(success);
    }
}

contract Helper {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

